class Torch
{
    public string Label;
    public int Fuel;

    public void Burn()
    {
        Fuel = Fuel - 1;
    }
}

class Camp
{
    public int Light()
    {
        Torch north = new Torch();
        north.Label = "North";
        north.Fuel = 5;
        north.Burn();

        Torch south = new Torch();
        south.Fuel = 9;
        return north.Fuel + south.Fuel;
    }
}
